SourceCode.Declaration:
/// <summary>
/// Carrier object passed from <c>AAXWHSLabelPreviewController</c> to the preview
/// dialog form (<c>AAXWHSLabelPreviewDialog</c>) via <c>Args.parmObject()</c>.
/// The dialog reads the rendered PNG list, the final token-substituted ZPL, the
/// source badge text, and the layout description from this object. Standard
/// parm-pattern class.
/// </summary>
public final class AAXWHSLabelPreviewContext
{
    private List    pngList;
    private str     finalZpl;
    private str     sourceZpl;      // RAW source (with $tokens$ / {{Header}}{{Row}}{{Footer}}) — the EDITABLE/SAVABLE text
    private boolean canSave;        // Whether the dialog may offer "Save to layout" for this layout type
    private str     badgeText;
    private str     layoutDescription;

    // Seed-record selection: the dialog re-renders by re-reading the
    // layout row (identity below) and calling AAXWHSLabelPreviewController::buildContext()
    // with a chosen seed record on the resolved seed table.
    private TableId layoutTableId;
    private RecId   layoutRecId;
    private TableId seedTableId;
    private RecId   seedRecId;
    private str     seedTableLabel;

    // Size-override carrier (dialog "Label size" box). Persists the user's chosen size across
    // re-renders/paging so the dialog can repopulate its controls from the context. When
    // overrideSize is false the renderer uses the label's own ^PW/^LL (or the 4x6 fallback).
    private boolean overrideSize;
    private real    overrideWidthIn;
    private real    overrideHeightIn;
    private int     overrideDpi;
}

Method.Source:
/// <summary>
/// Gets or sets the rendered PNG list (one <c>container</c> per ^XA..^XZ label block).
/// </summary>
/// <param name = "_pngList">The PNG <c>List</c> of containers to set.</param>
/// <returns>The current PNG <c>List</c>.</returns>
public List parmPngList(List _pngList = null)
{
    if (!prmIsDefault(_pngList))
    {
        pngList = _pngList;
    }

    return pngList;
}

/// <summary>
/// Gets or sets the final, token-substituted ZPL displayed beside the image.
/// </summary>
/// <param name = "_finalZpl">The final ZPL string to set.</param>
/// <returns>The current final ZPL string.</returns>
public str parmFinalZpl(str _finalZpl = '')
{
    if (!prmIsDefault(_finalZpl))
    {
        finalZpl = _finalZpl;
    }

    return finalZpl;
}

/// <summary>
/// Gets or sets the RAW SOURCE ZPL of the layout — the text WITH unresolved <c>$tokens$</c>
/// (and, for template layouts, the <c>{{Header}}/{{Row}}/{{Footer}}</c> blocks). This is the
/// text the dialog makes EDITABLE and saves back to the layout; it must never be the
/// token-substituted result (saving substituted text would destroy the layout's tokens).
/// </summary>
/// <param name = "_sourceZpl">The raw source ZPL to set.</param>
/// <returns>The current raw source ZPL.</returns>
public str parmSourceZpl(str _sourceZpl = '')
{
    if (!prmIsDefault(_sourceZpl))
    {
        sourceZpl = _sourceZpl;
    }

    return sourceZpl;
}

/// <summary>
/// Gets or sets whether the previewed layout's raw source may be saved back from the dialog.
/// True for ZPL-type WHSLabelLayout and WHSDocumentRoutingLayout rows; the dialog hides/disables
/// the Save button when false (e.g. Variables/VariablesScript layouts are not previewable here).
/// </summary>
/// <param name = "_canSave">The save-allowed flag to set.</param>
/// <returns>The current save-allowed flag.</returns>
public boolean parmCanSave(boolean _canSave = false)
{
    if (!prmIsDefault(_canSave))
    {
        canSave = _canSave;
    }

    return canSave;
}

/// <summary>
/// Gets or sets the source badge text ("Live record: %1" or "Sample data").
/// </summary>
/// <param name = "_badgeText">The badge text to set.</param>
/// <returns>The current badge text.</returns>
public str parmBadgeText(str _badgeText = '')
{
    if (!prmIsDefault(_badgeText))
    {
        badgeText = _badgeText;
    }

    return badgeText;
}

/// <summary>
/// Gets or sets the human-readable layout description shown in the dialog caption/header.
/// </summary>
/// <param name = "_layoutDescription">The layout description to set.</param>
/// <returns>The current layout description.</returns>
public str parmLayoutDescription(str _layoutDescription = '')
{
    if (!prmIsDefault(_layoutDescription))
    {
        layoutDescription = _layoutDescription;
    }

    return layoutDescription;
}

/// <summary>
/// Gets or sets the table id of the source layout row (WHSLabelLayout or
/// WHSDocumentRoutingLayout), so the dialog can re-read it to re-render.
/// </summary>
/// <param name = "_layoutTableId">The layout table id to set.</param>
/// <returns>The current layout table id.</returns>
/// <remarks>
/// Standard parm idiom: the controller always sets a non-zero layout table id, so the
/// prmIsDefault(0) guard never blocks a real assignment (X++ disallows non-constant
/// default parameter values, hence the constant 0 default rather than the member).
/// </remarks>
public TableId parmLayoutTableId(TableId _layoutTableId = 0)
{
    if (!prmIsDefault(_layoutTableId))
    {
        layoutTableId = _layoutTableId;
    }

    return layoutTableId;
}

/// <summary>
/// Gets or sets the RecId of the source layout row, so the dialog can re-read it to
/// re-render.
/// </summary>
/// <param name = "_layoutRecId">The layout RecId to set.</param>
/// <returns>The current layout RecId.</returns>
public RecId parmLayoutRecId(RecId _layoutRecId = 0)
{
    if (!prmIsDefault(_layoutRecId))
    {
        layoutRecId = _layoutRecId;
    }

    return layoutRecId;
}

/// <summary>
/// Gets or sets the resolved seed table id (the table the dialog's record selector
/// looks up).
/// </summary>
/// <param name = "_seedTableId">The seed table id to set.</param>
/// <returns>The current seed table id.</returns>
public TableId parmSeedTableId(TableId _seedTableId = 0)
{
    if (!prmIsDefault(_seedTableId))
    {
        seedTableId = _seedTableId;
    }

    return seedTableId;
}

/// <summary>
/// Gets or sets the RecId of the seed record used for token substitution. 0 means
/// "auto-resolve most-recent" (the default behavior).
/// </summary>
/// <param name = "_seedRecId">The seed RecId to set.</param>
/// <returns>The current seed RecId.</returns>
/// <remarks>
/// The member initializes to 0 (auto-resolve), so the prmIsDefault(0) guard is correct:
/// a non-zero pick is stored; a 0/auto-resolve pick simply leaves the member at its
/// initialized 0. Each Refresh builds a brand-new context, so there is no stale carry-over.
/// </remarks>
public RecId parmSeedRecId(RecId _seedRecId = 0)
{
    if (!prmIsDefault(_seedRecId))
    {
        seedRecId = _seedRecId;
    }

    return seedRecId;
}

/// <summary>
/// Gets or sets the display label of the seed table (DictTable.label()), shown in the
/// dialog's "Data source" group.
/// </summary>
/// <param name = "_seedTableLabel">The seed table label to set.</param>
/// <returns>The current seed table label.</returns>
public str parmSeedTableLabel(str _seedTableLabel = '')
{
    if (!prmIsDefault(_seedTableLabel))
    {
        seedTableLabel = _seedTableLabel;
    }

    return seedTableLabel;
}

/// <summary>
/// Gets or sets whether the user enabled the dialog's "Label size" override box. False means
/// the renderer uses the label's own ^PW/^LL (or the 4x6 fallback when it declares none).
/// </summary>
/// <param name = "_overrideSize">The override-enabled flag to set.</param>
/// <returns>The current override-enabled flag.</returns>
/// <remarks>
/// Constant-default + prmIsDefault idiom (as elsewhere in this class). The controller stamps a
/// fresh value onto a brand-new context on every render, and the member initializes to false,
/// so the prmIsDefault(false) guard never strands a real assignment (no stale carry-over).
/// </remarks>
public boolean parmOverrideSize(boolean _overrideSize = false)
{
    if (!prmIsDefault(_overrideSize))
    {
        overrideSize = _overrideSize;
    }

    return overrideSize;
}

/// <summary>
/// Gets or sets the override width in inches (dialog "Label size" box). The controller converts
/// inches to mm (*25.4) when passing the override into the render pipeline.
/// </summary>
/// <param name = "_overrideWidthIn">The override width in inches to set.</param>
/// <returns>The current override width in inches.</returns>
public real parmOverrideWidthIn(real _overrideWidthIn = 0)
{
    if (!prmIsDefault(_overrideWidthIn))
    {
        overrideWidthIn = _overrideWidthIn;
    }

    return overrideWidthIn;
}

/// <summary>
/// Gets or sets the override height in inches (dialog "Label size" box). The controller converts
/// inches to mm (*25.4) when passing the override into the render pipeline.
/// </summary>
/// <param name = "_overrideHeightIn">The override height in inches to set.</param>
/// <returns>The current override height in inches.</returns>
public real parmOverrideHeightIn(real _overrideHeightIn = 0)
{
    if (!prmIsDefault(_overrideHeightIn))
    {
        overrideHeightIn = _overrideHeightIn;
    }

    return overrideHeightIn;
}

/// <summary>
/// Gets or sets the override DPI (dialog "Label size" box). The controller converts DPI to dpmm
/// (round(dpi/25.4)) when passing the override into the render pipeline.
/// </summary>
/// <param name = "_overrideDpi">The override DPI to set.</param>
/// <returns>The current override DPI.</returns>
public int parmOverrideDpi(int _overrideDpi = 0)
{
    if (!prmIsDefault(_overrideDpi))
    {
        overrideDpi = _overrideDpi;
    }

    return overrideDpi;
}
